import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        super().__init__(n)
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Check every element in parallel; return results in order or raise Bad of lowest-index bad element."""
    from concurrent.futures import ThreadPoolExecutor

    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(check, x) for x in xs]

    results: list[int] = []
    for f in futures:
        exc = f.exception()
        if exc is not None:
            raise exc
        results.append(f.result())
    return results


def test_empty() -> None:
    assert all_even([]) == []


def test_all_even() -> None:
    assert all_even([2, 4, 6, 8]) == [2, 4, 6, 8]


def test_single_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 5, 4])
    assert exc_info.value.n == 5


def test_multiple_bad_raises_first_index() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 3, 4, 5, 6, 7])
    assert exc_info.value.n == 3


def test_first_element_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([9, 2, 4])
    assert exc_info.value.n == 9


def test_last_element_bad() -> None:
    with pytest.raises(Bad) as exc_info:
        all_even([2, 4, 6, 11])
    assert exc_info.value.n == 11

